                # event together: a failed write leaves nothing behind.
                self.store.attested_syncs.pop(key, None)
                self.store.forks.pop(tip_hash, None)
                self.store.truncate_audit_events(1)
                raise

            result = dict(summary)
            result["expires_at"] = expires_at
            return 201, result

