# Exact, ordered key sets of a batch Merkle-proof response document. They let
# verify_merkle_proof_bundle reject missing/extra keys *and* a wrong key order.
_BUNDLE_TOP_KEYS = ("height", "block_hash", "merkle_root", "transaction_ids", "proofs")
_BUNDLE_TX_KEYS = ("tx_id", "index")
_BUNDLE_PROOF_KEYS = ("tx_id", "index", "siblings")
_BUNDLE_SIBLING_KEYS = ("direction", "hash")


def _exact_keys(value: object, keys: tuple[str, ...]) -> bool:
    """True iff ``value`` is a dict with exactly ``keys``, in that insertion order."""
    return isinstance(value, dict) and tuple(value.keys()) == keys


def verify_merkle_proof_bundle(
    bundle: object,
    expected_block_hash: object,
    expected_merkle_root: object,
) -> bool:
    """Strictly verify a batch Merkle-proof bundle offline.

    The bundle mirrors POST /v1/blocks/{height}/proofs::

        {"height": H, "block_hash": B, "merkle_root": R,
         "transaction_ids": [tx_id, ...],   # ascending
         "proofs": [{"tx_id", "index", "siblings"}, ...]}  # tx_id order

    Every proof's leaf-to-root sibling path is re-hashed with the same pairing
    rules as :func:`merkle_root` (``sha256(left + right)`` hex pairs, a lone odd
    node paired with itself); the recomputed root must equal both the bundle's
    ``merkle_root`` and ``expected_merkle_root``, and ``block_hash`` must equal
    ``expected_block_hash``. The ``index`` of every proof must be the tx_id's
    position in ``transaction_ids``; tx_ids must be unique hex64 strings shared
    by both lists.

    Every defect — a missing/extra key, a wrong key order, a wrong type, a
    non-boolean/negative height, a duplicate/non-hex/non-string tx_id, list
    order/set mismatch, an out-of-range index, a path inconsistent with the
    index (including the phantom self-pair slot), an illegal direction or hash,
    excessive depth, a tampered root or block hash — returns False rather than
    raising.
    """
    try:
        if not _exact_keys(bundle, _BUNDLE_TOP_KEYS):
            return False
        if not _is_hex64(expected_block_hash) or not _is_hex64(expected_merkle_root):
            return False
        height = bundle["height"]
        block_hash = bundle["block_hash"]
        merkle_root = bundle["merkle_root"]
        transaction_ids = bundle["transaction_ids"]
        proofs = bundle["proofs"]

        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            return False
        if not _is_hex64(block_hash):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not isinstance(transaction_ids, list) or not transaction_ids:
            return False
        if not isinstance(proofs, list) or len(proofs) != len(transaction_ids):
            return False
        if any(not _is_hex64(tx_id) for tx_id in transaction_ids):
            return False
        # Unique tx_ids ...
        if len(set(transaction_ids)) != len(transaction_ids):
            return False
        # ... in ascending tx_id order, matching the block's leaf ordering.
        if transaction_ids != sorted(transaction_ids):
            return False

        positions = {tx_id: i for i, tx_id in enumerate(transaction_ids)}
        seen: set[str] = set()
        for proof in proofs:
            if not _exact_keys(proof, _BUNDLE_PROOF_KEYS):
                return False
            tx_id = proof["tx_id"]
            index = proof["index"]
            siblings = proof["siblings"]
            if not _is_hex64(tx_id) or tx_id not in positions:
                return False
            if tx_id in seen:
                return False
            seen.add(tx_id)
            if isinstance(index, bool) or not isinstance(index, int) or index < 0:
                return False
            # The index must be the tx_id's leaf position; a larger value is
            # out of range regardless of the hashes supplied.
            if index != positions[tx_id] or index >= len(transaction_ids):
                return False
            if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
                return False

            # Walk the path while checking it agrees with the index at every
            # level: an even position is the left child (sibling on its right),
            # an odd position the right child.
            depth = len(siblings)
            if index >= (1 << depth):
                return False
            current = tx_id
            position = index
            level_size = len(transaction_ids)
            for item in siblings:
                if not _exact_keys(item, _BUNDLE_SIBLING_KEYS):
                    return False
                direction = item["direction"]
                sibling_hash = item["hash"]
                if not _is_hex64(sibling_hash):
                    return False
                if level_size % 2 == 1:
                    # The last (even) node is paired with a copy of itself, so a
                    # genuine odd-level step always points right at that node; a
                    # left sibling equal to the current node addresses the
                    # phantom duplicate slot, which is never a real leaf.
                    if position == level_size - 1 and direction != "right":
                        return False
                if direction == "left":
                    if position % 2 == 0:
                        return False
                    if sibling_hash == current:
                        return False
                    pair = sibling_hash + current
                elif direction == "right":
                    if position % 2 == 1:
                        return False
                    pair = current + sibling_hash
                else:
                    return False
                current = sha256_hex(pair.encode("ascii"))
                position //= 2
                level_size = (level_size + 1) // 2

            if not hmac.compare_digest(current, merkle_root):
                return False

        # proofs must cover exactly transaction_ids, in the same tx_id order.
        if seen != set(transaction_ids):
            return False
        proof_ids = [proof["tx_id"] for proof in proofs]
        if proof_ids != transaction_ids:
            return False

        if not hmac.compare_digest(merkle_root, expected_merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


