python3 - <<'EOF'
import traceback, hmac
from ledger import crypto
from ledger.crypto import (_exact_keys, _is_hex64, _BUNDLE_TOP_KEYS, _BUNDLE_PROOF_KEYS,
    _BUNDLE_SIBLING_KEYS, MAX_MERKLE_DEPTH, sha256_hex, merkle_root)

def h(s): return crypto.sha256_hex(s.encode())
bh = h("block")
tx_ids = sorted([h("x")])
root = merkle_root(tx_ids)
bundle = {"height":1,"block_hash":bh,"merkle_root":root,"transaction_ids":tx_ids,
     "proofs":[{"tx_id":tx_ids[0],"index":0,"siblings":[]}]}

def check(bundle, expected_block_hash, expected_merkle_root):
    try:
        if not _exact_keys(bundle, _BUNDLE_TOP_KEYS): return ("top",)
        if not _is_hex64(expected_block_hash) or not _is_hex64(expected_merkle_root): return ("anchor hex",)
        height=bundle["height"]; block_hash=bundle["block_hash"]; mr=bundle["merkle_root"]
        tids=bundle["transaction_ids"]; proofs=bundle["proofs"]
        if isinstance(height,bool) or not isinstance(height,int) or height<0: return ("height",)
        if not _is_hex64(block_hash): return ("bh",)
        if not _is_hex64(mr): return ("mr",)
        if not isinstance(tids,list) or not tids: return ("tids",)
        if not isinstance(proofs,list) or not proofs: return ("proofs",)
        if any(not _is_hex64(t) for t in tids): return ("tids hex",)
        if len(set(tids))!=len(tids): return ("dup tids",)
        if tids != sorted(tids): return ("order tids",)
        if not hmac.compare_digest(merkle_root(tids), mr): return ("root recompute",)
        positions={t:i for i,t in enumerate(tids)}
        proof_ids=[]
        for proof in proofs:
            if not _exact_keys(proof,_BUNDLE_PROOF_KEYS): return ("proof keys",)
            tx_id=proof["tx_id"]; index=proof["index"]; siblings=proof["siblings"]
            if not _is_hex64(tx_id) or tx_id not in positions: return ("tx id",)
            if tx_id in proof_ids: return ("dup proof",)
            if isinstance(index,bool) or not isinstance(index,int): return ("index type",)
            if index != positions[tx_id] or not 0<=index<len(tids): return ("index map",)
            if not isinstance(siblings,list) or len(siblings)>MAX_MERKLE_DEPTH: return ("sib type",)
            depth=len(siblings)
            if index >= (1<<depth): return ("depth",)
            current=tx_id; position=index
            for item in siblings:
                if not _exact_keys(item,_BUNDLE_SIBLING_KEYS): return ("sib keys",)
                d=item["direction"]; sh=item["hash"]
                if not _is_hex64(sh): return ("sib hex",)
                if d=="left":
                    if position%2==0 or sh==current: return ("left path",)
                    pair=sh+current
                elif d=="right":
                    if position%2==1: return ("right path",)
                    pair=current+sh
                else: return ("direction",)
                current=sha256_hex(pair.encode("ascii")); position//=2
            if not hmac.compare_digest(current,mr): return ("path root",)
            proof_ids.append(tx_id)
        if proof_ids != sorted(proof_ids): return ("proof order",)
        if not hmac.compare_digest(mr,expected_merkle_root): return ("exp root",)
        if not hmac.compare_digest(block_hash,expected_block_hash): return ("exp bh",)
        return ("OK",)
    except Exception:
        traceback.print_exc()
        return ("EXC",)

print(check(bundle, bh, root))
EOF

